Let me write the optimized RMSNorm:

```cpp
template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    int tid = threadIdx.x;
    int bdim = blockDim.x;

    // Vectorized load: 8 elements at a time for fp16 (4 for fp32)
    constexpr int VEC = sizeof(float4) / sizeof(scalar_t);
    int vec_hidden = hidden_size / VEC;

    // Step 1: compute sum of squares using vectorized loads
    float sum_sq = 0.0f;
    for (int i = tid; i < vec_hidden; i += bdim) {
        float4 vec = reinterpret_cast<const float4*>(x)[i];
        // Extract and square each element
        const scalar_t* vals = reinterpret_cast<const scalar_t*>(&vec);
        #pragma unroll
        for (int j = 0; j < VEC; j++) {
            float val = static_cast<float>(vals[j]);
            sum_sq += val * val;
        }
    }
    // Handle remaining elements
    for (int i = tid + vec_hidden * VEC; i < hidden_size; i += bdim) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
    }

    // Warp-level reduction
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (bdim + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (tid == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    // Step 2: normalize and scale with vectorized loads/stores
    for (int i = tid; i < vec_hidden; i += bdim) {
        float4 vec_x = reinterpret_cast<const float4*>(x)[i];
        float4 vec_w = reinterpret_cast<const float4*>(weight)[i];
        scalar_t* vals_x = reinterpret_cast<scalar_t*>(&vec_x);
        const scalar_t* vals_w = reinterpret_cast<const scalar_t*>(&vec_w);
        float4 vec_out;
        scalar_t* vals_o = reinterpret_cast<scalar_t*>(&vec_out);
        #pragma unroll
        for (int j = 0; j < VEC; j++) {
            float val = static_cast<float>(vals_x[j]);
            float w = static_cast<float>(vals_w[j]);
            vals_o[j] = static_cast<scalar_t>(val * rms_inv * w);
        }
        reinterpret_cast<float4*>(o)[i] = vec_out;
    }
    // Handle remaining elements
    for (int i = tid + vec_hidden * VEC; i < hidden_size; i += bdim) {
        float val = static_cast<float>(__ldg(&x[i]));
        float w = static_cast<float>(__ldg(&weight[i]));
        o[i] = static_cast<scalar_t>(val * rms_inv * w);
    }
}
```

